<template>
  <div>
    <div :class="['date-range-picker', { 'with-separator': props.separator }]">
      <CalendarDropdown
        :flexWidth="props.flexWidth"
        :disabled="props.disabled || props.disabledStartDate"
        :title="props.firstLabel"
        v-model="startDate"
        :placeholder="props.firstPlaceholder"
        :min-date="minStartDate"
        :max-date="maxStartDate"
        :format-type="props.formatType"
        :alignment="props.firstAlignment"
        @buttom-sheet-shown="handleOffcanvasToggle"
        @close="emits('close:start')"
        :no-slash="props.noSlash"
      />
      <div v-if="props.separator" class="form-label d-block" style="top: 40px; position: relative; height: min-content;">s.d</div>
      <CalendarDropdown
        :flexWidth="props.flexWidth"
        :disabled="props.disabled || props.disabledEndDate"
        :title="props.secondLabel"
        v-model="endDate"
        :placeholder="props.secondPlaceholder"
        :min-date="minEndDate"
        :max-date="maxEndDate"
        :format-type="props.formatType"
        :alignment="props.secondAlignment"
        @buttom-sheet-shown="handleOffcanvasToggle"
        @close="emits('close:end')"
        :no-slash="props.noSlash"
      />
    </div>
    <div v-if="props.errorMessage || errorValidation" class="error-text mt-2">
      {{ props.errorMessage || errorValidation }}
    </div>
  </div>
</template>

<script setup>
import CalendarDropdown from './CalendarDropdown.vue';
import { computed } from 'vue'

const startDate = defineModel('startDate') // eslint-disable-line
const endDate = defineModel('endDate') // eslint-disable-line
const emits = defineEmits(['buttomSheetShown', 'close:start', 'close:end']) // eslint-disable-line

const errorValidation = computed(() => {
  if (startDate.value && endDate.value && startDate.value > endDate.value) {
    return 'Tanggal akhir harus lebih besar dari tanggal awal'
  } else {
    return null
  }
})

const props = defineProps({
  disabled: {
    type: Boolean,
    default: false
  },
  firstLabel: {
    type: String,
    default: 'Dari',
    required: true
  },
  secondLabel: {
    type: String,
    default: 'Hingga'
  },
  separator: {
    type: Boolean,
    default: false
  },
  firstPlaceholder: {
    type: String,
    default: 'DD / MM / YYYY'
  },
  secondPlaceholder: {
    type: String,
    default: 'DD / MM / YYYY'
  },
  minStartDate: {
    type: [Date, String],
  },
  maxStartDate: {
    type: [Date, String],
  },
  minEndDate: {
    type: [Date, String],
  },
  maxEndDate: {
    type: [Date, String],
  },
  minDate: {
    type: [Date, String],
  },
  maxDate: {
    type: [Date, String],
  },
  flexWidth: {
      type: Boolean,
      default: false
  },
  /**
   * @value date | short
   * @default date
   */
  formatType: {
    type: String,
    default: 'date'
  },
  errorMessage: {
    type: String
  },
  /**
   * @value start | center | end
   */
  firstAlignment: {
    type: String
  },
  /**
   * @value start | center | end
   */
  secondAlignment: {
    type: String
  },
  /**
   * remove slash from in out of range date
   */
  noSlash: {
    type: Boolean,
    default: false
  },
  disabledStartDate: {
    type: Boolean,
    default: false
  },
  disabledEndDate: {
    type: Boolean,
    default: false
  }
})

const formatDateString = (val) => {
  if (!val) return null
  if (typeof val === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(val)) {
    return val
  }
  const date = val instanceof Date ? val : new Date(val)
  if (isNaN(date.getTime())) return null
  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

const parseDateValue = (val) => {
  if (!val) return null
  if (val instanceof Date) return val
  if (typeof val === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(val)) {
    const [year, month, day] = val.split('-').map(Number)
    return new Date(year, month - 1, day)
  }
  const date = new Date(val)
  return isNaN(date.getTime()) ? null : date
}

const minStartDate = computed(() => {
  return formatDateString(props.minStartDate || props.minDate)
})

const maxEndDate = computed(() => {
  return formatDateString(props.maxEndDate || props.maxDate)
})

const minEndDate = computed(() => {
  const propMinEnd = parseDateValue(props.minEndDate || props.minDate)
  const curStart = parseDateValue(startDate.value)
  if (propMinEnd && curStart) {
    return formatDateString(propMinEnd.getTime() > curStart.getTime() ? propMinEnd : curStart)
  } else if (propMinEnd) {
    return formatDateString(propMinEnd)
  } else if (curStart) {
    return formatDateString(curStart)
  } else {
    return null
  }
})

const maxStartDate = computed(() => {
  const propMaxStart = parseDateValue(props.maxStartDate || props.maxDate)
  const curEnd = parseDateValue(endDate.value)
  if (propMaxStart && curEnd) {
    return formatDateString(propMaxStart.getTime() < curEnd.getTime() ? propMaxStart : curEnd)
  } else if (propMaxStart) {
    return formatDateString(propMaxStart)
  } else if (curEnd) {
    return formatDateString(curEnd)
  } else {
    return null
  }
})

const handleOffcanvasToggle = (value) => {
  emits('buttomSheetShown', value)
}
</script>

<script>
export default {
  name: 'DateRangePicker'
}
</script>

<style scoped>
.form-label {
  display: none;
}

.date-range-picker {
  display: flex;
  gap: 16px;
}

.error-text {
  color: var(--g-kit-red-50);
  margin-bottom: 16px;
}
</style>
